using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using Newtonsoft.Json;
public static class InstallUnderSleeveFit {
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");const string path="Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab";const string target="Assets/_Sandbox/Characters/Ethan_V2/Meshes/EthanV2_Body_ShirtFit.asset";var root=PrefabUtility.LoadPrefabContents(path);try{var body=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="BAKED_body_lod0_mesh");var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2_73_Baked.fbx").GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name==body.name).sharedMesh;var mesh=UnityEngine.Object.Instantiate(source);mesh.name="EthanV2_Body_ShirtFit";var offsets=JsonConvert.DeserializeObject<float[][]>(File.ReadAllText("Data/EthanV2/ClothingRepair/body_fit_offsets.json"));var matrices=body.bones.Select((bone,i)=>root.transform.worldToLocalMatrix*bone.localToWorldMatrix*source.bindposes[i]).ToArray();var vertices=source.vertices;
 using(var counts=source.GetBonesPerVertex())using(var weights=source.GetAllBoneWeights()){int at=0;for(int i=0;i<vertices.Length;i++){var blend=new Matrix4x4();for(int j=0;j<counts[i];j++){var w=weights[at++];var m=matrices[w.boneIndex];for(int row=0;row<4;row++)for(int col=0;col<4;col++)blend[row,col]+=m[row,col]*w.weight;}var d=offsets[i];vertices[i]+=blend.inverse.MultiplyVector(new Vector3(d[0],d[1],d[2]));}}
 mesh.vertices=vertices;mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();if(mesh.triangles.Length!=source.triangles.Length||!mesh.triangles.SequenceEqual(source.triangles))throw new Exception("Body topology must remain complete");var existing=AssetDatabase.LoadAssetAtPath<Mesh>(target);if(existing){EditorUtility.CopySerialized(mesh,existing);UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,target);body.sharedMesh=mesh;PrefabUtility.SaveAsPrefabAsset(root,path);AssetDatabase.SaveAssets();return new{body=target,triangles=mesh.triangles.Length/3,originalTriangles=source.triangles.Length/3,noTrianglesRemoved=true};}finally{PrefabUtility.UnloadPrefabContents(root);}}
}
